#define NULL 0

class IGOIconManager
{
public:
  enum { ICON_NUM_TYPES = 10 };
  class IconResource { public: unsigned char pad[12]; unsigned char timesDisplayed; };
  class Icon { public: char pad[64]; IconResource *resource; float y, vy, sizeInterp, colorInterp; bool show; unsigned char state; };

  int numIcons;
  unsigned char currentSetting;
  unsigned char currentSpawn;
  float spawnDelay;
  float initSpawnTime;
  float spawnTimer;
  float lastDropTime;
  unsigned char repeatCount[ICON_NUM_TYPES];
  IconResource *airIconResources;
  IconResource *faceIconResources;
  IconResource *tubeIconResources;
  IconResource *specialAirIconResources;
  IconResource *specialFaceIconResources;
  IconResource *specialTubeIconResources;
  int numAirIconResources;
  int numFaceIconResources;
  int numTubeIconResources;
  int numSpecialAirIconResources;
  int numSpecialFaceIconResources;
  int numSpecialTubeIconResources;
  bool getIceTexture[6];
  Icon nextIcon;
  int activeIcon;
  int completedIcons;
  unsigned char numEffectIcons;
  unsigned char effectType;
  float effectTime;
  bool chainedIcons;
  int iconCounter;
  int iconSpawnCounter;
  float buttonTimer;
  int prepareFailure;
  bool failure;
  bool enableNewIcons;
  bool drawButtons;
  bool showTimer;
  bool nextEnable;
  bool done_before;
  unsigned char numChains;
  unsigned char numFrozen;
  unsigned char numGlowing;
  float time;
  float timeLastQueueChange;
  IconResource *lastIcon;
  int sameIconCount;
  int lastIconGroup;
  int sameIconGroupCount;
  bool prepPop;
  float popTime;
  bool prepMidPop[5];
  float midPopTime[5];
  int tsSize;

  void Reset(void);
};

void IGOIconManager::Reset(void)
{
  int i;

  numIcons = 0;

  currentSetting = 0;
  currentSpawn   = 0xFF;

  spawnDelay = initSpawnTime;
	spawnTimer = spawnDelay;
  lastDropTime = 0.0f;

  for(i=0; i<ICON_NUM_TYPES; i++)
    repeatCount[i] = 0;

  for(i=0; i<numAirIconResources; i++)
    airIconResources[i].timesDisplayed = 0;
  for(i=0; i<numFaceIconResources; i++)
    faceIconResources[i].timesDisplayed = 0;
  for(i=0; i<numTubeIconResources; i++)
    tubeIconResources[i].timesDisplayed = 0;
  for(i=0; i<numSpecialAirIconResources; i++)
    specialAirIconResources[i].timesDisplayed = 0;
  for(i=0; i<numSpecialFaceIconResources; i++)
    specialFaceIconResources[i].timesDisplayed = 0;
  for(i=0; i<numSpecialTubeIconResources; i++)
    specialTubeIconResources[i].timesDisplayed = 0;

  for(i=0; i<6; i++)
    getIceTexture[i] = true;

  nextIcon.show = false;
  nextIcon.resource = NULL;
  activeIcon = 0;
  completedIcons = 0;
  numEffectIcons = 0;
  effectType = 0;
  effectTime = 0.0f;
  chainedIcons = false;
  iconCounter = 0;
  iconSpawnCounter = 0;
  buttonTimer = 0.0f;
  prepareFailure = false;
  failure = false;
  enableNewIcons = true;
  drawButtons = false;
  showTimer = false;
  nextEnable = true;

  done_before = false;

  numChains = 0;
  numFrozen = 0;
  numGlowing = 0;

  time = 0.0f;
  timeLastQueueChange = 0.0f;

  lastIcon            = NULL;
  sameIconCount       = 0;
  lastIconGroup       = -1;
  sameIconGroupCount  = 0;

  prepPop = false;
  popTime = 0.0f;

  for(i=0; i<5; i++)
  {
    prepMidPop[i] = false;
    midPopTime[i] = 0.0f;
  }

  tsSize = 0;
}
